import type { KoreanUnit, KoreanWord, KoreanExercise } from './korean-course-data';
import { koreanListeningChecks } from './korean-listening-data';

export type ExtendedContent = {
  grammar: string; passage: string; question: string; answer: string; distractors: string[];
  writingTask: string; minCharacters: number; maxCharacters: number;
};
export type ExtendedUnit = KoreanUnit & { extension: ExtendedContent };
type Row = [string, string, string, string[], string[], string, string, string, string[], string];
const parse = (rows: string[]): KoreanWord[] => rows.map(row => {
  const [ko, id, en] = row.split('|');
  if (!ko || !id || !en) throw new Error(`Missing translation: ${row}`);
  return { ko, id, en };
});

